<script setup lang="ts">
import { computed, markRaw, ref } from 'vue'
import { CommandPalette, createCommandPaletteProvider, createCommandPaletteRegistry, createCommandRegistryPaletteProvider, useSelection, useWidgetNavigation } from 'widgetforge'
import { useDemoControls, type DemoThemeName } from '../demo-controls'
import { playgroundCommands } from '../playground-commands'
import { colonyOptions, colonySelectionKey } from '../selection-demo'
const navigation=useWidgetNavigation(),controls=useDemoControls(),colony=useSelection(colonySelectionKey),selectedColony=colony.value
if(selectedColony.value===null)colony.select('ARC-01')
const theme=computed(()=>controls.theme()),canUndo=computed(()=>controls.canUndo?.()??false),canRedo=computed(()=>controls.canRedo?.()??false),workspaceMode=computed(()=>controls.workspaceMode?.()??'normal'),layoutNames=computed(()=>controls.layoutNames?.()??[]),activeLayout=computed(()=>controls.activeLayout?.()??''),developerMode=computed(()=>controls.developerMode?.()??false),feedOnline=computed(()=>controls.feedOnline?.()??true)
function openMarket():void{navigation.navigate({widgetId:'market.ticker',parameters:{commodity:'METALS',rows:10}})}function openColony():void{navigation.navigate({widgetId:'planet.summary',parameters:{planetId:selectedColony.value??'ARC-01',compact:false}})}function openProduction():void{navigation.navigate({widgetId:'economy.production'})}function openInventory():void{navigation.navigate({widgetId:'economy.inventory'})}function openOrders():void{navigation.navigate({widgetId:'economy.orders'})}function openAlerts():void{navigation.navigate({widgetId:'demo.alerts'})}function openModal():void{navigation.navigate({widgetId:'demo.modal-review'})}
function changeTheme(event:Event):void{const select=event.target;if(select instanceof HTMLSelectElement)controls.setTheme(select.value as DemoThemeName)}
function changeLayout(event:Event):void{const select=event.target;if(select instanceof HTMLSelectElement&&select.value)controls.loadLayout?.(select.value)}
function changeColony(event:Event):void{const select=event.target;if(select instanceof HTMLSelectElement)colony.select(select.value)}
function toggleEdit():void{controls.setWorkspaceMode?.(workspaceMode.value==='edit'?'normal':'edit')}function toggleLock():void{controls.setWorkspaceMode?.(workspaceMode.value==='locked'?'normal':'locked')}function toggleDevTools():void{controls.setDeveloperMode?.(!developerMode.value)}function toggleFeed():void{feedOnline.value?controls.simulateFeedFailure?.():controls.recoverFeed?.()}
const palette=ref<{open:()=>Promise<void>}|null>(null)
const paletteRegistry=markRaw(createCommandPaletteRegistry([
  createCommandRegistryPaletteProvider(playgroundCommands,navigation,'demo-commands'),
  createCommandPaletteProvider('workspace-actions',()=>[
    {id:'workspace:reset',label:'Reset workspace',category:'Workspace',keywords:['default','layout'],execute:()=>{void controls.resetWorkspace()}},
    {id:'workspace:undo',label:'Undo layout change',category:'Workspace',keywords:['history'],shortcut:'Ctrl+Z',disabled:!canUndo.value,execute:()=>controls.undo?.()},
    {id:'workspace:redo',label:'Redo layout change',category:'Workspace',keywords:['history'],shortcut:'Ctrl+Y',disabled:!canRedo.value,execute:()=>controls.redo?.()},
    {id:'workspace:edit',label:workspaceMode.value==='edit'?'Leave layout edit mode':'Enter layout edit mode',category:'Workspace',keywords:['pane','layout'],execute:toggleEdit},
    {id:'workspace:lock',label:workspaceMode.value==='locked'?'Unlock workspace':'Lock workspace',category:'Workspace',keywords:['pane','layout'],execute:toggleLock},
    {id:'data:feed',label:feedOnline.value?'Simulate economy feed failure':'Reconnect economy feed',category:'Data',keywords:['network','reconnect','error'],execute:toggleFeed},
    {id:'developer:devtools',label:developerMode.value?'Disable Developer Mode':'Enable Developer Mode',category:'Developer',keywords:['debug','devtools','diagnostics'],shortcut:'Ctrl+Shift+D',execute:toggleDevTools},
    ...layoutNames.value.map((name)=>({id:`layout:${name}`,label:`Load ${name} layout`,category:'Layouts',keywords:['workspace','preset',name],execute:()=>controls.loadLayout?.(name)})),
  ]),
  createCommandPaletteProvider('widget-shortcuts',()=>[
    {id:'widget:market',label:'Open Commodity Exchange',category:'Economy',keywords:['market','ticker'],execute:openMarket},
    {id:'widget:production',label:'Open Production',category:'Economy',keywords:['production','factory'],execute:openProduction},
    {id:'widget:inventory',label:'Open Inventory',category:'Economy',keywords:['inventory','stock'],execute:openInventory},
    {id:'widget:orders',label:'Open Orders',category:'Economy',keywords:['orders','trade'],execute:openOrders},
    {id:'widget:colony',label:'Open Colony Overview',category:'Widgets',keywords:['planet',selectedColony.value??'ARC-01'],execute:openColony},
    {id:'widget:alerts',label:'Open Operations Alerts',category:'Widgets',keywords:['alerts'],execute:openAlerts},
    {id:'widget:modal',label:'Open Critical Operations Review',category:'Widgets',keywords:['modal','review'],execute:openModal},
  ]),
]))
</script>
<template><nav class="workspace-topbar" aria-label="Simulation navigation"><div class="workspace-topbar__brand"><span class="workspace-topbar__mark">WF</span><div><strong>Orbital Exchange</strong><span>Sector Helios · Economy Network</span></div></div><div class="workspace-topbar__nav"><button type="button" data-demo-nav="production" @click="openProduction">Production</button><button type="button" data-demo-nav="inventory" @click="openInventory">Inventory</button><button type="button" data-demo-nav="market" @click="openMarket">Market</button><button type="button" data-demo-nav="orders" @click="openOrders">Orders</button><button type="button" data-demo-nav="alerts" @click="openAlerts">Alerts</button><button type="button" data-demo-nav="modal" @click="openModal">Modal</button><button type="button" data-demo-action="palette" title="Command palette (Ctrl+K)" @click="palette?.open()">Palette</button></div><div class="workspace-topbar__tools"><select :value="selectedColony" aria-label="Colony selection" @change="changeColony"><option v-for="id in colonyOptions" :key="id" :value="id">{{id}}</option></select><select v-if="layoutNames.length" :value="activeLayout" aria-label="Workspace layout" @change="changeLayout"><option value="" disabled>Custom</option><option v-for="name in layoutNames" :key="name" :value="name">{{name}}</option></select><button type="button" data-demo-action="feed" :aria-pressed="!feedOnline" @click="toggleFeed">{{feedOnline?'Fail feed':'Reconnect'}}</button><button type="button" data-demo-action="devtools" :class="{'workspace-topbar__active':developerMode}" :aria-pressed="developerMode" title="Developer Mode · then Ctrl+Shift+D" @click="toggleDevTools">DevTools</button><button type="button" data-demo-action="edit" :class="{'workspace-topbar__active':workspaceMode==='edit'}" :aria-pressed="workspaceMode==='edit'" @click="toggleEdit">{{workspaceMode==='edit'?'Editing':'Edit'}}</button><button type="button" data-demo-action="lock" :class="{'workspace-topbar__active':workspaceMode==='locked'}" :aria-pressed="workspaceMode==='locked'" @click="toggleLock">{{workspaceMode==='locked'?'Unlock':'Lock'}}</button><span class="workspace-topbar__online" :data-online="String(feedOnline)"><i/> {{feedOnline?'Network online':'Feed offline'}}</span><select :value="theme" aria-label="Theme" @change="changeTheme"><option value="forge-dark">Dark</option><option value="forge-light">Light</option></select><button type="button" data-demo-action="reset" class="workspace-topbar__reset" @click="controls.resetWorkspace">Reset layout</button></div><CommandPalette ref="palette" :registry="paletteRegistry"/></nav></template>
<style scoped>.workspace-topbar{height:100%;display:flex;align-items:center;gap:var(--wf-space-md);padding:0 var(--wf-space-md);background:var(--wf-color-surface);color:var(--wf-color-text);font-size:var(--wf-font-size-sm);overflow:hidden}.workspace-topbar__brand{display:flex;align-items:center;gap:var(--wf-space-sm);min-width:185px}.workspace-topbar__mark{display:grid;place-items:center;width:30px;height:30px;border:1px solid var(--wf-color-accent);border-radius:var(--wf-radius-sm);color:var(--wf-color-accent);font-weight:var(--wf-font-weight-bold);letter-spacing:.06em}.workspace-topbar__brand div{display:grid;line-height:1.15}.workspace-topbar__brand span:last-child{margin-top:2px;color:var(--wf-color-text-muted);font-size:var(--wf-font-size-xs)}.workspace-topbar__nav{display:flex;align-items:center;gap:2px;flex:1;height:100%}.workspace-topbar button,.workspace-topbar select{height:30px;border:1px solid transparent;border-radius:var(--wf-radius-sm);background:transparent;color:var(--wf-color-text);font:inherit}.workspace-topbar button{padding:0 var(--wf-space-xs);cursor:pointer}.workspace-topbar button:hover:not(:disabled){background:var(--wf-color-hover);border-color:var(--wf-color-border)}.workspace-topbar button:focus-visible,.workspace-topbar select:focus-visible{outline:2px solid var(--wf-color-focus);outline-offset:1px}.workspace-topbar__active{background:var(--wf-color-selected)!important;border-color:var(--wf-color-focus)!important}.workspace-topbar__tools{display:flex;align-items:center;justify-content:flex-end;gap:var(--wf-space-xs);white-space:nowrap}.workspace-topbar__online{display:flex;align-items:center;gap:6px;color:var(--wf-color-text-muted);font-size:var(--wf-font-size-xs)}.workspace-topbar__online i{width:7px;height:7px;border-radius:50%;background:var(--wf-color-success);box-shadow:0 0 8px var(--wf-color-success)}.workspace-topbar__online[data-online="false"] i{background:var(--wf-color-danger);box-shadow:0 0 8px var(--wf-color-danger)}.workspace-topbar select{max-width:105px;padding:0 var(--wf-space-xs);border-color:var(--wf-color-border);background:var(--wf-color-surface-raised)}.workspace-topbar__reset{color:var(--wf-color-text-muted)!important}@media(max-width:1180px){.workspace-topbar__brand span:last-child,.workspace-topbar__online,.workspace-topbar__reset,.workspace-topbar__nav button[data-demo-nav="alerts"],.workspace-topbar__nav button[data-demo-nav="modal"],.workspace-topbar__tools>button[data-demo-action="edit"],.workspace-topbar__tools>button[data-demo-action="lock"]{display:none}.workspace-topbar{gap:var(--wf-space-xs)}.workspace-topbar__brand{min-width:auto}}</style>
